<?php
namespace App\Http\Controllers;
use App\Models\User;
use App\Services\Passwords;
use App\Services\Verification;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Laravel\Socialite\Facades\Socialite;
class AuthController extends Controller {
 public function __construct(private Passwords $passwords,private Verification $verification) {}
 private function start(Request $r,User $u): array { Auth::login($u); $r->session()->regenerate(); $r->session()->put('studio_stamp',$u->security_stamp); return ['user'=>$u->dto(),'csrf'=>$r->session()->token()]; }
 public function session(Request $r){ $u=$r->user(); if($u && ($r->session()->get('studio_stamp')!==$u->security_stamp || !($u->verification_exempt || $u->email_verified_at))) { Auth::logout(); $u=null; } return ['user'=>$u?->dto(),'csrf'=>$r->session()->token()]; }
 public function options(){ return ['google'=>filled(config('services.google.client_id')) && filled(config('services.google.client_secret')),'email'=>$this->verification->ready()]; }
 public function login(Request $r){ $v=$r->validate(['email'=>'required|string|max:254','password'=>'required|string|max:128']); $u=User::where('email',strtolower(trim($v['email'])))->orWhere('username',strtolower(trim($v['email'])))->first(); abort_unless($u && $this->passwords->verify($u,$v['password']),401,'Email or password is incorrect.'); abort_unless($u->email_verified_at || $u->verification_exempt,403,'Verify your email before signing in.'); $this->passwords->upgrade($u,$v['password']); return $this->start($r,$u); }
 public function logout(Request $r){ Auth::logout(); $r->session()->invalidate(); $r->session()->regenerateToken(); return ['success'=>true]; }
 public function signup(Request $r){ abort_unless($this->verification->ready(),503,'Email signup requires SMTP or Resend configuration.'); $v=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|max:254','password'=>'required|string|min:12|max:128','confirmPassword'=>'required|same:password']); $address=strtolower(trim($v['email'])); abort_if(User::where('email',$address)->exists(),422,'An account with this email exists.'); $u=User::create(['name'=>$v['name'],'email'=>$address,'password'=>Hash::make($v['password']),'role'=>'member','security_stamp'=>(string)Str::uuid()]); $this->verification->send($u); return response()->json(['verificationRequired'=>true,'email'=>$u->email,'message'=>'Check your inbox and verify your email before signing in.'],201); }
 public function resend(Request $r){ $v=$r->validate(['email'=>'required|email']); abort_unless($this->verification->ready(),503,'Email verification is not configured.'); $u=User::where('email',strtolower($v['email']))->first(); if($u) $this->verification->send($u); return ['message'=>'If this account needs verification, a link has been sent.']; }
 public function verify(Request $r){ $token=$r->query('token',''); $ok=false; if(preg_match('/^[a-f0-9]{64}$/',$token)) $ok=User::where('verification_hash',hash('sha256',$token))->where('verification_expires','>',now())->update(['email_verified_at'=>now(),'verification_hash'=>null,'verification_expires'=>null])===1; return redirect('/login?verification='.($ok?'complete':'expired')); }
 public function users(){ return User::all()->map->dto(); }
 public function saveUser(Request $r){ $v=$r->validate(['id'=>'nullable|integer','name'=>'required|string|max:100','email'=>'required|email|max:254','role'=>'required|in:owner,editor,member','password'=>'nullable|string|min:12|max:128']); return DB::transaction(function() use($v){ $owners=User::where('role','owner')->lockForUpdate()->get(); $u=isset($v['id'])?User::findOrFail($v['id']):new User; $email=strtolower($v['email']); abort_if(User::where('email',$email)->where('id','!=',$u->id ?? 0)->exists(),422,'Email already in use.'); abort_if($u->role==='owner' && $v['role']!=='owner' && $owners->count()<=1,422,'Keep at least one owner.'); abort_if(!$u->exists && empty($v['password']),422,'Enter an initial password.'); if($u->exists && $u->email!==$email) { $u->email_verified_at=null; $u->verification_exempt=false; $u->google_id=null; $u->verification_hash=null; } $u->name=$v['name']; $u->email=$email; $u->role=$v['role']; if(!empty($v['password'])) { $u->password=Hash::make($v['password']); $u->password_scheme='laravel'; $u->legacy_salt=null; } $u->security_stamp=(string)Str::uuid(); $u->save(); return $u->dto(); }); }
 public function deleteUser(Request $r,string $id){ return DB::transaction(function() use($r,$id){ $owners=User::where('role','owner')->lockForUpdate()->get(); $u=User::findOrFail($id); abort_if((string)$r->user()->id===$id,422,'You cannot delete your current account.'); abort_if($u->role==='owner' && $owners->count()<=1,422,'Keep at least one owner.'); $u->delete(); return ['success'=>true]; }); }
 public function invite(string $id){ $this->verification->send(User::findOrFail($id)); return ['message'=>'Verification email sent.']; }
 public function googleStart(){ if(!$this->options()['google']) return redirect('/login?auth=google-unavailable'); return Socialite::driver('google')->redirect(); }
 public function googleCallback(Request $r){ try { $profile=Socialite::driver('google')->user(); abort_unless(($profile->user['email_verified'] ?? $profile->user['verified_email'] ?? false)===true,403); $email=strtolower($profile->getEmail()); $u=User::where('google_id',$profile->getId())->orWhere('email',$email)->first(); if($u) { abort_if($u->verification_exempt || !$u->email_verified_at || $u->email!==$email || ($u->google_id && $u->google_id!==$profile->getId()),403); $u->google_id=$profile->getId(); $u->save(); } else $u=User::create(['name'=>$profile->getName() ?: 'Pixode member','email'=>$email,'password'=>Hash::make(Str::random(64)),'role'=>'member','email_verified_at'=>now(),'google_id'=>$profile->getId(),'security_stamp'=>(string)Str::uuid()]); $this->start($r,$u); return redirect('/admin'); } catch(\Throwable $e){ report($e); return redirect('/login?auth=google-failed'); } }
}
